# -*- coding: utf-8 -*-
"""Сборка листка 22.09: что взято, что отложено, кандидаты. Выход руками не правится."""
import json, re, html, io
P = json.load(open('/tmp/pul.json', encoding='utf-8'))
def cl(s): return re.sub(r'\s+',' ', s or '').strip()
def g(c,*p):
    for k,v in c.items():
        if any(k.startswith(x) for x in p): return v
    return ''
def find(src, frag):
    for c in P:
        if c['src']==src and re.search(re.escape(frag)+r'(?![0-9])', c['id'], re.I): return c
    return None

VZYATO = [
 ('КРУЖОК','перебор','Перечислите все тройки различных натуральных чисел, дающих в сумме 10. (Тройки, отличающиеся только порядком, считаем одинаковыми.)','формулы нет и не нужна. Пара к треугольнику с четвёрками в сумме 15'),
 ('КРУЖОК','отрезок','а) Сколько чисел в ряду 17, 18, 19, …, 122, 123? б) Сколько чисел в ряду −17, −16, …, −1, 0, 1, …, 122, 123? в) Из книги выпала пачка листов: на первой выпавшей странице номер 143, на последней — 328. Сколько листов выпало?','три пункта, сведено из двух задач. Пункт в) добавляет вторую ловушку — две страницы на листе'),
 ('КРУЖОК','сумма','Сколько существует двузначных чисел, у которых а) первая цифра меньше второй? б) сумма цифр двузначна?','ПОСЛЕДНИМ. Два решения а): сумма 1+…+8 = 36 и 90−9−9 пополам'),
 ('КРУЖОК','вкл-искл','В колоде 36 карт четырёх мастей. Для гадания Аза взяла все пики и все картинки (валетов, дам и королей), а остальные карты отложила. Сколько карт выбрала Аза?','9 + 12 − 3 = 18'),
 ('КРУЖОК','разность','Сколько чисел от 1 до 100 НЕ делятся на 3?','100 − 33 = 67. Чистое вычитание, ни одного умножения'),
 ('ТРЕУГОЛЬНИК','перебор','Перечислите все четвёрки различных натуральных чисел, дающих в сумме 15. (Четвёрки, отличающиеся только порядком, считаем одинаковыми.)','та же идея, что в кружке с тройками, но перебор длиннее'),
 ('ТРЕУГОЛЬНИК','отрезок','Какая будет общая формула для количества целых чисел от m до n? (Сами m и n тоже включаются.)','абстрактная версия кружка: сразу буквы вместо чисел'),
 ('ТРЕУГОЛЬНИК','разность','У скольких чисел от 1 до 2019 в записи есть по крайней мере две различные цифры?','считать наоборот: вычесть числа из одинаковых цифр'),
 ('ТРЕУГОЛЬНИК','вкл-искл','Среди чисел 1, 2, …, 300 Валя подчеркнула все те, у которых общий делитель с числом 99 больше 1. Сколько всего чисел она подчеркнула?','100 + 27 − 9 = 118'),
 ('РОМБ','перебор','Сколькими способами можно заплатить 37 рублей? Есть только монеты в 1, 2 и 5 рублей. Способы, отличающиеся только порядком монет, считаем одинаковыми.','по числу пятёрок: лесенка 18, 15, 12, …'),
 ('РОМБ','разность','У каждого из тридцати шестиклассников есть одна ручка, один карандаш и одна линейка. После олимпиады оказалось, что 26 учеников потеряли ручку, 23 — линейку и 21 — карандаш. Найдите наименьшее возможное количество шестиклассников, потерявших всё три предмета.','не потеряли 4+7+9 = 20, значит потерявших всё три не меньше 10'),
 ('РОМБ','инструмент','В классе 25 школьников. Известно, что среди любых трёх из них есть двое друзей. Докажите, что найдётся школьник, у которого не меньше двенадцати друзей.','если у кого-то не больше 11 друзей, он не дружит с 25−1−11 = 13 остальными, а те обязаны дружить попарно. Вычитание плюс одно рассуждение'),
 ('РОМБ','разность','Двенадцать малышей вышли во двор играть в песочнице. Каждый, кто принёс ведёрко, принёс и совочек. Забыли дома ведёрко девять малышей, забыли дома совочек двое. На сколько меньше малышей, которые принесли ведёрко, чем тех, которые принесли совочек?','включение одного множества в другое плюс вычитание. Число 12 в ответ не входит вовсе'),
 ('РОМБ','отрезок','На каждой перемене Робин-Бобин съедает по шоколадке. Сколько шоколадок он мог съесть за апрель, если уроки были каждый день, кроме воскресений, 1 апреля была среда, а всего за месяц было 100 уроков?','перемен на одну меньше, чем уроков, В КАЖДЫЙ ДЕНЬ ОТДЕЛЬНО — надо посчитать учебные дни апреля. Три разных счёта в одной задаче'),
 ('ГРОБ','перебор','Выпишите все десятизначные числа, у которых первая цифра равна количеству нулей в записи, вторая — количеству единиц, третья — количеству двоек, и так далее, а десятая — количеству девяток.','переформулировано по вашей идее: вместо «существует ли» — «выпишите все», и задача становится переборной. Ключ: сумма всех десяти цифр равна 10'),
 ('ГРОБ','разность','Сколько существует четырёхзначных чисел, сумма цифр которых больше 33?','счёт наоборот от 9999: недобор до 36 равен 0, 1 или 2, все случаи выписываются руками. Формулы нет'),
 ('РОМБ','перебор·зонд','Сколькими способами можно набрать 20 рублей монетами по 1, 2, 5 и 10 рублей? Пункты: а) 10 рублей; б) 20 рублей.','ответ 40. Пара к монетам 37: тот же приём, но номиналов четыре — усложнение ровно по модулю предыдущей задачи. 2 пункта'),
 ('РОМБ','сумма','Сколько существует трёхзначных чисел, сумма цифр которых а) равна 4? б) не превосходит 4?','ответ б) 20. Разбить по первой цифре и сложить: 10+6+3+1. Чистое правило суммы руками, формулы нет. 2 пункта'),
 ('РОМБ','инструмент','После заседания Булль пошёл в трактир, там сидела компания из 10 островитян. Первый сказал: «Среди нас нет ни одного рыцаря», второй: «Среди нас не более одного рыцаря», третий: «Среди нас не более двух рыцарей», и так далее до десятого. Сколько среди них рыцарей? Пункты: а) для 10 островитян; б) а если бы их было 20?','ответ 5 (и 10). Заявление номер i истинно ровно когда рыцарей не больше i−1 — дальше чистый счёт. ВОЗВРАТ ТЕМЫ: рыцари и лжецы были 15.09, это хвост по Р21. 2 пункта'),
 ('РОМБ','вкл-искл','Как изменится правая часть формулы включения-исключения для трёх множеств, если из множества A удалить элемент, который а) не входил ни в B, ни в C? б) входил в A и B, но не в C? в) входил во все три?','во всех трёх случаях правая часть уменьшается на 1 — синхронно с левой. Убирая элементы по одному, обе части дойдут до нуля, значит формула верна. Прямое продолжение карт. 3 пункта'),
 ('РОМБ','ЗОНД произведение','Сколько раз встречается цифра 7 в записи чисел а) от 1 до 100? б) от 1 до 1000? в) Сколько ЧИСЕЛ от 1 до 1000 содержат хотя бы одну семёрку?','ВОЗВРАЩЕНА как зонд. Ответ 20, 300, 271. Здесь произведение нужно по-настоящему — смотрим, кто из класса им владеет. 3 пункта'),
 ('РОМБ','ЗОНД произведение','Выбираются пары чисел из набора 1, 2, …, 31. У скольких пар сумма входящих в них чисел будет нечётной?','ВОЗВРАЩЕНА как зонд. 16·15 = 240. Шаг «сумма нечётна ⇔ одно чётное, другое нет» — содержательный, само умножение тривиальное. 1 пункт'),
 ('ГРОБ','сумма','Можно ли разложить 99 орехов на 10 кучек так, чтобы любые две кучки отличались, но не более чем в три раза?','можно, и единственным способом: 5, 6, 7, 8, 9, 10, 12, 13, 14, 15. Оценка снизу и сверху получается счётом, произведения и двойного подсчёта нет. Условие понятно всем'),
]
