w('<title>Листок 22.09 — сборка</title>')
w('<link href="https://fonts.googleapis.com/css2?family=Unbounded:wght@900&family=IBM+Plex+Serif:wght@400;600&family=IBM+Plex+Mono:wght@400&display=swap" rel="stylesheet">')
w('<style>%s</style></head><body><div class="w">' % CSS)
w('<h1>Листок 22.09<br>сборка</h1><div class="sub">комбинаторика · блок «Перебор и правило суммы» · пара 22.09</div>')
w('<div class="hint"><b>Конструкция.</b> Кружки и треугольники ДУБЛИРУЮТ друг друга по навыкам — это две дороги к четвёрке. ')
w('Разница только в уровне абстракции: кружки на конкретных числах и с бóльшим счётом, треугольники сразу для произвольных m и n и с вдвое меньшим числом пунктов. ')
w('Обязательные навыки, оба пути покрывают все четыре: <b>перебор без формулы · сколько чисел от m до n · сумма и разность · два множества с пересечением</b>. ')
w('Умножения в обязательных не требуем. Небольшое произведение допустимо в ромбах — как ЗОНД, посмотреть, кто им владеет.<br><br>')
PUNKTY = {'КРУЖОК':8,'ТРЕУГОЛЬНИК':4,'РОМБ':18,'ГРОБ':3}
w('<b>Сейчас в листке: ' + ' · '.join('%s — %d задач, %d баллов' % (n.lower(), sum(1 for v in VZYATO if v[0]==n), PUNKTY[n]) for n in ('КРУЖОК','ТРЕУГОЛЬНИК','РОМБ','ГРОБ')) + '</b><br>')
w('Всего %d задач. Потолок: база 8 + ромбы 18 + гробы 3 = <b>29 баллов</b>, один школьник идёт по одной дороге из двух, так что его потолок меньше.<br><br>' % len(VZYATO))
w('Сейчас взято: кружков %d, треугольников %d, ромбов %d, гробов %d.</div>' % (
  sum(1 for v in VZYATO if v[0]=='КРУЖОК'), sum(1 for v in VZYATO if v[0]=='ТРЕУГОЛЬНИК'),
  sum(1 for v in VZYATO if v[0]=='РОМБ'), sum(1 for v in VZYATO if v[0]=='ГРОБ')))
w('<h2>Взято — %d</h2>' % len(VZYATO))
for lvl,tema,usl,note in VZYATO:
    w('<div class="c" data-l="%s"><span class="tg">%s</span><span class="tg">%s</span>' % (lvl,lvl.lower(),tema))
    w('<p class="u">%s</p><p class="n">%s</p></div>' % (html.escape(usl), html.escape(note)))
w('<h2>Отложено — вернуться позже</h2>')
for nm,usl,why in OTLOZH:
    w('<div class="c"><span class="tg">%s</span><p class="u">%s</p><p class="n">куда: %s</p></div>' % (html.escape(nm),html.escape(usl),html.escape(why)))
def block(title, lst, lvl, lim):
    w('<h2>%s — %d в базе, показано %d</h2>' % (title, len(lst), min(lim,len(lst))))
    for c in lst[:lim]:
        w('<div class="c" data-l="%s"><span class="tg">%s</span><span class="tg">%s</span><span class="tg">%s</span>' % (
            lvl, c['rol'], c['dolya'], html.escape(c['src'])))
        w('<details><summary>%s</summary>' % html.escape(cl(g(c,'УСЛОВИЕ'))))
        w('<p class="u">%s</p>' % html.escape(cl(g(c,'УСЛОВИЕ'))))
        ot=cl(g(c,'ОТВЕТ'));  pk=cl(g(c,'ПУНКТЫ'))
        if ot: w('<p class="n">ответ: %s</p>' % html.escape(ot[:420]))
        if pk: w('<p class="n">пункты: %s</p>' % html.escape(pk[:420]))
        w('</details></div>')
block('Кандидаты в ромбы', KAND_R, 'РОМБ', 16)
block('Кандидаты в гробы', KAND_G, 'ГРОБ', 14)
w('</div></body></html>')
